package local.dinerdash.prototype;

import android.app.*;
import android.content.SharedPreferences;
import android.os.Bundle;
import android.view.*;
import android.view.inputmethod.InputMethodManager;
import android.widget.*;
import java.util.*;

public final class MainActivity extends Activity implements GameView.Listener,MenuView.Listener {
    private GameEngine game;
    private GameView board;
    private MenuView menus;
    private GameAudio audio;
    private AssetStore assets;
    private SharedPreferences saved,progress;
    private FrameLayout root;
    private EditText profileInput;
    private String afterLogin="career_setup";
    @Override public void onCreate(Bundle bundle){super.onCreate(bundle);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);saved=getSharedPreferences("career",MODE_PRIVATE);assets=new AssetStore(this);audio=new GameAudio(this,assets);audio.enabled=saved.getBoolean("sound",true);audio.musicEnabled=saved.getBoolean("music",true);
        root=new FrameLayout(this);root.setBackgroundColor(0xff000000);root.setOnApplyWindowInsetsListener((v,insets)->{if(menus!=null&&menus.fullscreen){android.view.DisplayCutout cut=android.os.Build.VERSION.SDK_INT>=28?insets.getDisplayCutout():null;v.setPadding(cut==null?0:cut.getSafeInsetLeft(),cut==null?0:cut.getSafeInsetTop(),cut==null?0:cut.getSafeInsetRight(),cut==null?0:cut.getSafeInsetBottom());}else v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});
        game=new GameEngine(LevelData.get(Math.max(1,Math.min(50,saved.getInt("current",1)))));board=new GameView(this,game,this,assets,audio);root.addView(board,new FrameLayout.LayoutParams(-1,-1));menus=new MenuView(this,assets,this);root.addView(menus,new FrameLayout.LayoutParams(-1,-1));setContentView(root);loadProfile();menus.music=audio.musicEnabled;menus.sfx=audio.enabled;menus.fullscreen=saved.getBoolean("fullscreen",true);immersive();title();
        // ADB QA launch is invisible to the game menus and does not unlock career progress.
        if(getIntent().hasExtra("qa_level"))start(Math.max(1,Math.min(50,getIntent().getIntExtra("qa_level",1))),false);
    }
    private void immersive(){getWindow().getDecorView().setSystemUiVisibility(menus.fullscreen?View.SYSTEM_UI_FLAG_FULLSCREEN|View.SYSTEM_UI_FLAG_HIDE_NAVIGATION|View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY|View.SYSTEM_UI_FLAG_LAYOUT_STABLE|View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN|View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION:View.SYSTEM_UI_FLAG_LAYOUT_STABLE);}
    @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus&&menus!=null)immersive();}
    private void loadProfile(){menus.profileSlot=Math.max(0,Math.min(9,saved.getInt("profileSlot",0)));for(int i=0;i<10;i++)menus.profiles[i]=saved.getString("profile"+i,"");if(menus.profiles[0].isEmpty()&&saved.contains("current")&&!saved.getBoolean("profileProgressMigrated",false)){menus.profiles[0]="Player";saved.edit().putString("profile0","Player").apply();}
        menus.profile=menus.profiles[menus.profileSlot];progress=getSharedPreferences("career_profile_"+menus.profileSlot,MODE_PRIVATE);
        // Preserve the old shared save only for the player selected when updating.
        if(!saved.getBoolean("profileProgressMigrated",false)){SharedPreferences.Editor e=progress.edit();for(Map.Entry<String,?> v:saved.getAll().entrySet()){String k=v.getKey();if((k.equals("current")||k.equals("unlocked")||k.equals("lives")||k.equals("totalStars")||k.equals("totalScore")||k.matches("best[0-9]+"))&&v.getValue() instanceof Integer)e.putInt(k,(Integer)v.getValue());}e.apply();saved.edit().putBoolean("profileProgressMigrated",true).apply();}
        menus.current=Math.max(1,Math.min(50,progress.getInt("current",1)));menus.selected=menus.current;menus.unlocked=Math.max(menus.current,Math.min(50,progress.getInt("unlocked",1)));menus.gameOver=progress.getInt("lives",3)==0;for(int i=0;i<50;i++)menus.experts[i]=progress.getInt("best"+(i+1),0)>=LevelData.get(i+1).expert;loadScores();}
    private void loadScores(){String[] names={"Margaret","Indra","Jorge","Tamesha","Aziz","Jack","Aiden","Milagros","Wu","Suzie"};int[] career={20000,15000,10000,7500,6000,5000,4000,3000,2000,1000},endless={2000,1500,1000,750,500,400,300,200,100,50};for(int mode=0;mode<4;mode++)for(int i=0;i<10;i++){String key="hs"+mode+"_"+i;menus.scoreNames[mode][i]=saved.getString(key+"name",names[i]);menus.scoreValues[mode][i]=saved.getInt(key+"score",(mode==0?career:endless)[i]);}}
    private void submitScore(int mode,int score){loadScores();for(int rank=0;rank<10;rank++)if(score>menus.scoreValues[mode][rank]){for(int i=9;i>rank;i--){menus.scoreNames[mode][i]=menus.scoreNames[mode][i-1];menus.scoreValues[mode][i]=menus.scoreValues[mode][i-1];}menus.scoreNames[mode][rank]=menus.profile.isEmpty()?"Player":menus.profile;menus.scoreValues[mode][rank]=score;SharedPreferences.Editor e=saved.edit();for(int i=0;i<10;i++){String key="hs"+mode+"_"+i;e.putString(key+"name",menus.scoreNames[mode][i]).putInt(key+"score",menus.scoreValues[mode][i]);}e.apply();break;}}
    private void title(){game.paused=true;board.setVisibility(View.GONE);menus.show("title_screen");audio.menuMusic();}
    private void show(String screen){game.paused=true;menus.show(screen);}
    private void resumeGame(){menus.setVisibility(View.GONE);board.setVisibility(View.VISIBLE);game.paused=false;audio.resume();}
    private void start(int n,boolean afterWin){game=new GameEngine(LevelData.get(n));game.stars=progress.getInt("lives",game.level.stars);game.totalStars=Math.max(game.stars,progress.getInt("totalStars",game.level.stars));menus.gameOver=false;board.setGame(game);board.setVisibility(View.VISIBLE);menus.game=game;menus.intro=game.level.intro;audio.startMusic(game.level.stage);show("startlevel");}
    private void endless(int stage,int diff){game=new GameEngine(LevelData.endless(stage,diff));menus.gameOver=false;board.setGame(game);board.setVisibility(View.VISIBLE);menus.game=game;menus.intro="Welcome to the Endless Shift!\nKeep your customers happy and earn upgrades to improve your restaurant.";audio.startMusic(stage);show("startlevel");}
    private void profileEditor(int slot){if(!finishProfileInput())return;menus.profileSlot=slot;if(!menus.profiles[slot].isEmpty()){menus.invalidate();return;}float scale=Math.min(menus.getWidth()/800f,menus.getHeight()/600f),ox=(menus.getWidth()-800*scale)/2,oy=(menus.getHeight()-600*scale)/2;profileInput=new EditText(this);profileInput.setSingleLine(true);profileInput.setTypeface(assets.mrB);profileInput.setTextSize(17);profileInput.setHint("New Player");profileInput.setTextColor(0xff222222);profileInput.setBackgroundColor(0xfff6f0e3);profileInput.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_DONE);FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(Math.round(268*scale),Math.round(40*scale));p.leftMargin=Math.round(ox+250*scale);p.topMargin=Math.round(oy+(105+slot*40)*scale);root.addView(profileInput,p);profileInput.setOnEditorActionListener((v,action,e)->{finishProfileInput();return true;});profileInput.requestFocus();((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).showSoftInput(profileInput,InputMethodManager.SHOW_IMPLICIT);}
    private boolean finishProfileInput(){if(profileInput==null)return true;String name=profileInput.getText().toString().trim().replaceAll("\\s+"," ");if(name.isEmpty()){profileInput.setError("Please type in a name.");return false;}for(int i=0;i<menus.profiles.length;i++)if(i!=menus.profileSlot&&menus.profiles[i].trim().replaceAll("\\s+"," ").equalsIgnoreCase(name)){profileInput.setError("That name is already taken.");return false;}menus.profiles[menus.profileSlot]=name;saved.edit().putString("profile"+menus.profileSlot,name).apply();discardProfileInput();return true;}
    private void discardProfileInput(){if(profileInput==null)return;((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(profileInput.getWindowToken(),0);root.removeView(profileInput);profileInput=null;menus.invalidate();}
    @Override public void menuAction(String key){String screen=menus.screen;if(screen.equals("title_screen")){switch(key){case "career_button":case "endless_button":afterLogin=key.equals("career_button")?"career_setup":"endless_setup";if(menus.profile.isEmpty())show("login");else {loadProfile();show(afterLogin);}break;case "login_button":afterLogin="title_screen";show("login");break;case "help_button":menus.page=1;show("help");break;case "hiscore_button":menus.hiscoreMode=0;loadScores();show("hiscore");break;case "options_button":menus.underlay="title_screen";show("options");break;case "quit_button":finish();break;}return;}
        if(screen.equals("career_setup")){if(key.equals("menu_button")){title();return;}if(key.startsWith("lvlbutton_")){String[] a=key.split("_");menus.selected=(Integer.parseInt(a[1])-1)*10+Integer.parseInt(a[2]);menus.invalidate();return;}if(key.equals("play_button")||key.equals("newgame_button")){if(key.equals("newgame_button")){progress.edit().putInt("current",menus.selected).putInt("lives",LevelData.get(menus.selected).stars).putInt("totalStars",LevelData.get(menus.selected).stars).putInt("totalScore",0).apply();menus.gameOver=false;if(menus.selected==1){menus.page=1;show("comic");}else start(menus.selected,false);}else if(!menus.gameOver)start(menus.selected,false);}return;}
        if(screen.equals("comic")){if(key.equals("arrow")){if(++menus.page>3)start(1,false);else menus.invalidate();}return;}
        if(screen.equals("endless_setup")){if(key.equals("menu_button")){title();return;}if(key.startsWith("rest_")){menus.selected=Integer.parseInt(key.substring(5));menus.underlay="endless_setup";show("endless_difficulty");}return;}
        if(screen.equals("endless_difficulty")){if(key.equals("closediff")){show("endless_setup");return;}if(key.startsWith("diff_"))endless(menus.selected,Integer.parseInt(key.substring(5)));return;}
        if(screen.equals("login")){if(key.startsWith("box_")){profileEditor(Integer.parseInt(key.substring(4))-1);return;}if(key.equals("cancel")){discardProfileInput();loadProfile();title();return;}if(key.equals("delete")){discardProfileInput();menus.profiles[menus.profileSlot]="";menus.profile="";saved.edit().remove("profile"+menus.profileSlot).apply();getSharedPreferences("career_profile_"+menus.profileSlot,MODE_PRIVATE).edit().clear().apply();menus.invalidate();return;}if(key.equals("play")){if(!finishProfileInput())return;if(menus.profiles[menus.profileSlot].isEmpty()){profileEditor(menus.profileSlot);return;}menus.profile=menus.profiles[menus.profileSlot];saved.edit().putInt("profileSlot",menus.profileSlot).apply();loadProfile();show(afterLogin);}return;}
        if(screen.equals("options")){switch(key){case "music_on":case "music_off":audio.musicEnabled=menus.music=key.endsWith("on");saved.edit().putBoolean("music",menus.music).apply();if(menus.music)audio.menuMusic();else audio.stop();break;case "sfx_on":case "sfx_off":audio.enabled=menus.sfx=key.endsWith("on");saved.edit().putBoolean("sound",menus.sfx).apply();break;case "fs_on":case "fs_off":menus.fullscreen=key.endsWith("on");saved.edit().putBoolean("fullscreen",menus.fullscreen).apply();immersive();break;case "okbutton":show(menus.underlay);break;}menus.invalidate();return;}
        if(screen.equals("help")){if(key.equals("menubutton")){title();return;}if(key.equals("next"))menus.page=Math.min(6,menus.page+1);if(key.equals("previous"))menus.page=Math.max(1,menus.page-1);if(key.equals("credits"))menus.page=6;if(key.equals("instructions"))menus.page=1;menus.invalidate();return;}
        if(screen.equals("hiscore")){if(key.equals("menubutton"))title();else {if(key.equals("leftarrow"))menus.hiscoreMode=Math.max(0,menus.hiscoreMode-1);if(key.equals("rightarrow"))menus.hiscoreMode=Math.min(3,menus.hiscoreMode+1);menus.invalidate();}return;}
        if(screen.equals("endless_shop")){if(key.equals("continue_button")){resumeGame();return;}if(key.startsWith("item_")){int index=Integer.parseInt(key.substring(5))-1;if(index<menus.upgradeChoices.size()){game.applyUpgrade(menus.upgradeChoices.get(index));menus.upgradeChoices=game.upgradeChoices();menus.invalidate();}}return;}
        if(screen.equals("startlevel")){if(key.equals("okbutton"))resumeGame();return;}
        if(screen.equals("pause")){if(key.equals("nobutton"))resumeGame();else if(key.equals("yesbutton"))title();return;}
        if(screen.equals("endlevel")){if(menus.gameOver){menus.hiscoreMode=game.level.endless?game.level.difficulty:0;loadScores();board.setVisibility(View.GONE);show("hiscore");return;}if(game.won&&game.level.number<50)start(game.level.number+1,true);else start(game.level.number,false);}
    }
    @Override public void update(GameEngine g){board.updateAccessibility();}
    @Override public void pauseGame(){game.paused=true;audio.pause();show("pause");}
    @Override public void shop(){if(!game.level.endless||game.availableUpgrades<=0)return;menus.game=game;menus.upgradeChoices=game.upgradeChoices();show("endless_shop");}
    @Override public void finished(GameEngine g){game.paused=true;menus.game=g;if(g.level.endless){menus.gameOver=true;menus.totalScore=g.score;menus.result="GAME OVER";submitScore(g.level.difficulty,g.score);}else{int lives=g.won?g.stars:Math.max(0,g.stars-1);int next=g.won?Math.min(50,g.level.number+1):g.level.number;if(g.won&&g.level.number<50&&g.level.number%10==0)lives=LevelData.get(next).stars;
            menus.gameOver=lives==0||g.won&&g.level.number==50;g.stars=lives;int total=progress.getInt("totalScore",0)+(g.won?g.score:0);SharedPreferences.Editor e=progress.edit();
            // The original final shift submits its score without advancing the resume checkpoint.
            if(!(g.won&&g.level.number==50))e.putInt("current",next).putInt("unlocked",Math.max(next,progress.getInt("unlocked",1))).putInt("lives",lives).putInt("totalStars",Math.max(lives,g.totalStars)).putInt("totalScore",total);if(g.won)e.putInt("best"+g.level.number,Math.max(g.score,progress.getInt("best"+g.level.number,0)));e.apply();menus.totalScore=total;menus.result=g.won?g.level.succeed:g.level.fail;if(menus.gameOver)submitScore(0,total);}show("endlevel");}
    @Override public void onBackPressed(){if(profileInput!=null){discardProfileInput();loadProfile();return;}if(menus.getVisibility()!=View.VISIBLE)pauseGame();else if(menus.screen.equals("pause"))resumeGame();else if(menus.screen.equals("title_screen"))finish();else {if(menus.screen.equals("login"))loadProfile();title();}}
    @Override protected void onResume(){super.onResume();if(board!=null)board.setActive(true);if(audio!=null)audio.resume();}
    @Override protected void onPause(){if(board!=null)board.setActive(false);if(audio!=null)audio.pause();super.onPause();}
    @Override protected void onDestroy(){if(audio!=null)audio.close();super.onDestroy();}
}
